def prod_signs(arr):
    if not arr:
        return None
    signs = [1 for _ in arr]
    for i in range(len(arr)):
        if arr[i] < 0:
            signs[i] = -1
        elif arr[i] == 0:
            signs[i] = 0
    return sum(abs(x) * signs[i] for i, x in enumerate(arr))
